prompt --application/shared_components/security/authentications/sch_auth_simple_fn
begin
wwv_flow_imp_shared.create_authentication(
 p_id=>wwv_flow_imp.id(128684849736869281619)
,p_name=>'sch_auth_simple_fn'
,p_scheme_type=>'NATIVE_CUSTOM'
,p_attribute_03=>'sch_auth_simple_fn '
,p_attribute_05=>'N'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- The function is defined with the name ''sch_auth_simple_fn''.',
'-- This name must match the one specified in your APEX authentication scheme settings.',
'-- It accepts two input parameters:',
'-- 1. p_username: The username entered by the user on the login form.',
'-- 2. p_password: The password entered by the user on the login form.',
'-- The function is declared to return a BOOLEAN value (either TRUE or FALSE),',
'-- which tells the APEX engine whether the login was successful or not.',
'FUNCTION sch_auth_simple_fn (',
'    p_username IN VARCHAR2,',
'    p_password IN VARCHAR2',
') RETURN BOOLEAN',
'IS',
'    -- This line declares a local variable named ''l_user_rec''.',
'    -- The ''%ROWTYPE'' attribute makes this variable a record structure that exactly',
'    -- mirrors the columns of the ''sch_app_user'' table. This is a convenient way',
'    -- to hold an entire row of data fetched from the table without having to',
'    -- declare a separate variable for each column (e.g., l_user_name, l_password, etc.).',
'    l_user_rec      sch_app_user%ROWTYPE;',
'BEGIN',
'    -- This marks the beginning of the main executable block of the function.',
'',
'    -- This is an inner PL/SQL block used for exception handling. It allows us to',
'    -- gracefully handle the specific case where a user is not found in the database.',
'    BEGIN',
'        -- This is the core SQL query to find the user.',
'        -- ''SELECT *'' instructs the database to retrieve all columns for the matching row.',
'        SELECT *',
'        -- The ''INTO l_user_rec'' clause tells the database to place the retrieved',
'        -- row of data into the record variable we declared earlier.',
'        INTO   l_user_rec',
'        -- ''FROM sch_app_user'' specifies the table we are querying.',
'        FROM   sch_app_user',
'        -- This is the filtering condition to find the correct user.',
'        -- ''UPPER(user_name) = UPPER(p_username)'' makes the comparison case-insensitive.',
'        -- It converts both the stored username and the entered username to uppercase',
'        -- before comparing them, so ''PARENT1'', ''parent1'', and ''Parent1'' will all match.',
'        WHERE  UPPER(user_name) = UPPER(p_username)',
'          -- This is an additional security check to ensure that the user''s account',
'          -- is currently active and allowed to log in.',
'          AND  is_active_yn = ''Y'';',
'',
'    -- This ''EXCEPTION'' block catches errors that occur within the ''BEGIN...END'' block above.',
'    EXCEPTION',
'        -- This specific handler, ''WHEN NO_DATA_FOUND'', triggers if the SELECT statement',
'        -- does not find any rows that match the WHERE clause. This is the expected',
'        -- error when a user enters a username that doesn''t exist or is marked as inactive.',
'        WHEN NO_DATA_FOUND THEN',
'            -- If the user is not found, we write a detailed message to the APEX debug log.',
'            -- This is crucial for troubleshooting login issues. The ''%s'' is a placeholder',
'            -- that will be replaced by the value of ''p_username''.',
'            apex_debug.message(''DIAGNOSTIC: User "%s" not found or is inactive.'', p_username);',
'            -- The function immediately stops and returns FALSE, indicating to the',
'            -- APEX engine that the authentication has failed.',
'            RETURN FALSE;',
'    END;',
'',
'    -- If the code reaches this point, it means a user was successfully found in the',
'    -- database and their record is now stored in the ''l_user_rec'' variable.',
'',
'    -- This is the insecure part of the diagnostic function.',
'    -- It performs a direct, character-by-character comparison between the password',
'    -- entered by the user (p_password) and the value stored in the ''password''',
'    -- column of the user''s record (l_user_rec.password).',
'    -- This will only evaluate to TRUE if the password was stored as plain, unencrypted text.',
'    IF l_user_rec.password = p_password THEN',
'',
'        -- If the passwords match, we write a success message to the debug log.',
'        -- This confirms that the login was successful and that it was because of a',
'        -- plain text match, highlighting the security risk.',
'        apex_debug.message(''DIAGNOSTIC: Login success for user "%s" using plain text match.'', p_username);',
'        -- The function returns TRUE, signaling a successful login to the APEX engine.',
'        RETURN TRUE;',
'',
'    ELSE',
'        -- This block executes if the ''IF'' condition is false (i.e., the passwords do not match).',
'',
'        -- A failure message is logged, indicating a password mismatch.',
'        apex_debug.message(''DIAGNOSTIC: Password mismatch for user "%s".'', p_username);',
'',
'        -- This is a critical debugging step. To help understand why the match failed,',
'        -- we log the first 20 characters of the value that is actually stored in the',
'        -- database''s ''password'' column. This helps diagnose issues like unwanted',
'        -- whitespace, unexpected character encoding, or if the password is, in fact,',
'        -- hashed (in which case it would look like random characters).',
'        apex_debug.message(''DIAGNOSTIC: Stored value starts with: %s'', SUBSTR(l_user_rec.password, 1, 20));',
'        ',
'        -- The function returns FALSE to indicate an authentication failure.',
'        RETURN FALSE;',
'',
'    END IF;',
'',
'-- This is the main exception handler for the entire function.',
'EXCEPTION',
'    -- ''WHEN OTHERS'' is a catch-all that will trap any unexpected error that was not',
'    -- handled by the more specific ''NO_DATA_FOUND'' exception handler above.',
'    -- This could be due to issues like database permissions, table access problems, etc.',
'    WHEN OTHERS THEN',
'        -- It logs a detailed error message, including the username that was being',
'        -- processed and the specific Oracle error message (retrieved via ''sqlerrm'').',
'        -- This is vital for debugging systemic or environmental problems.',
'        apex_debug.error(''DIAGNOSTIC: Unexpected error for user "%s": %s'', p_username, sqlerrm);',
'        ',
'        -- As a security precaution, any unexpected error should always result in a',
'        -- failed login. The function returns FALSE.',
'        RETURN FALSE;',
'',
'-- Marks the end of the function definition.',
'END;',
''))
,p_invalid_session_type=>'LOGIN'
,p_use_secure_cookie_yn=>'N'
,p_ras_mode=>0
,p_version_scn=>15703845145241
);
end;
