,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    g.FIRST_NAME,',
'    g.LAST_NAME,',
'    sg.RELATIONSHIP_CODE AS RELATIONSHIP, -- e.g. Father, Mother',
'    sg.PRIMARY_CONTACT_YN AS IS_PRIMARY,',
'    g.EMAIL,',
'    g.PHONE_PRIMARY,',
'    g.PHONE_ALT,',
'    g.CITY',
'FROM',
'    SCH_GUARDIAN g',
'JOIN',
'    SCH_STUDENT_GUARDIAN sg ON g.GUARDIAN_ID = sg.GUARDIAN_ID',
'WHERE',
'    sg.STUDENT_ID = :P20_STUDENT_ID',
'ORDER BY',
'    -- Sorts so Primary Contacts appear at the top',
'    sg.PRIMARY_CONTACT_YN DESC, ',
'    g.LAST_NAME;'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
