,p_display_sequence=>60
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    t.TERM_NAME,',
'    c.COURSE_CODE,',
'    c.COURSE_NAME,',
'    cl.SECTION_CODE,',
'    cl.ROOM_NUMBER,',
'    -- Fetches the teacher''s username/email (or name if available in your user table)',
'    u.USER_NAME AS TEACHER,',
'    se.STATUS,',
'    se.FINAL_GRADE',
'FROM',
'    SCH_STUDENT_ENROLLMENT se',
'JOIN',
'    SCH_CLASSES cl ON se.CLASS_ID = cl.CLASS_ID',
'JOIN',
'    SCH_COURSES c ON cl.COURSE_ID = c.COURSE_ID',
'JOIN',
'    SCH_ACADEMIC_TERMS t ON cl.ACADEMIC_TERM_ID = t.ACADEMIC_TERM_ID',
'LEFT JOIN',
'    SCH_APP_USER u ON cl.TEACHER_ID = u.APP_USER_ID',
'WHERE',
'    se.STUDENT_ID = :P20_STUDENT_ID',
'ORDER BY',
'    t.START_DATE DESC, -- Shows the most recent semesters first',
'    c.COURSE_NAME;',
''))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2538654340625403440
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
