,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    at.SCHOOL_YEAR,',
'    c.COURSE_NAME,',
'    -- Pivot Logic: Check the Term Number and grab the grade',
'    MAX(CASE WHEN at.TERM_NUMBER = 1 THEN se.FINAL_GRADE END) AS "Semester 1",',
'    MAX(CASE WHEN at.TERM_NUMBER = 2 THEN se.FINAL_GRADE END) AS "Semester 2",',
'    MAX(CASE WHEN at.TERM_NUMBER = 3 THEN se.FINAL_GRADE END) AS "Semester 3",',
'    MAX(CASE WHEN at.TERM_NUMBER = 4 THEN se.FINAL_GRADE END) AS "Semester 4",',
'    -- Optional: Calculate an approximate average if grades are numeric, ',
'    -- or just show the status',
'    MAX(se.STATUS) AS CURRENT_STATUS',
'FROM',
'    SCH_STUDENT_ENROLLMENT se',
'JOIN',
'    SCH_CLASSES cl ON se.CLASS_ID = cl.CLASS_ID',
'JOIN',
'    SCH_COURSES c ON cl.COURSE_ID = c.COURSE_ID',
'JOIN',
'    SCH_ACADEMIC_TERMS at ON cl.ACADEMIC_TERM_ID = at.ACADEMIC_TERM_ID',
'JOIN',
'    SCH_STUDENT s ON se.STUDENT_ID = :P20_STUDENT_ID',
'WHERE',
'    -- Replace this with your specific filter (e.g., :P1_STUDENT_ID)',
'    s.STUDENT_ID = :P20_STUDENT_ID',
'GROUP BY',
'    at.SCHOOL_YEAR,',
'    c.COURSE_NAME',
'ORDER BY',
'    at.SCHOOL_YEAR DESC,',
'    c.COURSE_NAME;',
''))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2538654340625403440
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
