wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(132107857745776601528)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load data based on user'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT',
'        s.STUDENT_ID,',
'        s.FIRST_NAME,',
'        s.LAST_NAME,',
'        -- Subquery to find the ID of the Primary Guardian',
'        (SELECT sg.GUARDIAN_ID',
'         FROM SCH_STUDENT_GUARDIAN sg',
'         WHERE sg.STUDENT_ID = s.STUDENT_ID',
'           AND sg.PRIMARY_CONTACT_YN = ''Y''',
'         FETCH FIRST 1 ROWS ONLY)',
'    INTO',
'        :P20_STUDENT_ID,',
'        :P20_FIRST_NAME,',
'        :P20_LAST_NAME,',
'        :P20_GUARDIAN_ID',
'    FROM',
'        SCH_APP_USER u',
'    JOIN',
'        SCH_STUDENT s ON u.STUDENT_ID = s.STUDENT_ID',
'    WHERE',
'        -- Match the logged-in user (case-insensitive)',
'        UPPER(u.USER_NAME) = UPPER(:APP_USER);',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        -- Fail silently if the logged-in user is not a student',
'        NULL;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>132107857745776601528
);
end;
/
