 p_id=>wwv_flow_imp.id(264141442076319654636)
,p_plug_name=>'Guardian Records'
,p_parent_plug_id=>wwv_flow_imp.id(131684861998245294714)
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>30
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    g.GUARDIAN_ID,',
'    g.FIRST_NAME,',
'    g.LAST_NAME,',
'    g.EMAIL,',
'    g.PHONE_PRIMARY,',
'    g.PHONE_ALT,',
'    g.ADDRESS1,',
'    g.ADDRESS2,',
'    g.CITY,',
'    g.STATE_CODE,',
'    g.POSTAL_CODE',
'FROM',
'    SCH_APP_USER u',
'JOIN',
'    SCH_GUARDIAN g ON u.GUARDIAN_ID = g.GUARDIAN_ID',
'JOIN',
'    SCH_APP_USER_ROLE aur ON u.APP_USER_ID = aur.APP_USER_ID',
'WHERE',
'    -- 1. Anchor to the specific user',
'    UPPER(u.USER_NAME) = UPPER(:APP_USER)',
'',
'    -- 2. Ensure the user is linked to a guardian profile',
'    AND u.GUARDIAN_ID IS NOT NULL',
'',
'    -- 3. Security Check: Confirm the user has an active ''PARENT'' role',
'    AND aur.ROLE_CODE = ''PARENT'' -- Or whatever your role code is',
'    AND aur.IS_ACTIVE = ''Y''',
'    AND TRUNC(SYSDATE) BETWEEN aur.EFFECTIVE_FROM AND NVL(aur.EFFECTIVE_TO, TRUNC(SYSDATE));',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'302_TEST'
,p_ai_enabled=>false
);
