wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(131718210706449984879)
,p_plug_name=>'Parent_My_Students_Main'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    s.STUDENT_ID,',
'    sg.GUARDIAN_ID,',
'    s.FIRST_NAME,',
'    s.LAST_NAME,',
'    s.STUDENT_NO,',
'    s.GRADE_LEVEL_CODE,',
'    sg.RELATIONSHIP_CODE,',
'    sg.PRIMARY_CONTACT_YN,',
'    s.EMAIL AS STUDENT_EMAIL',
'FROM',
'    -- Step 2: Start with the SCH_APP_USER table to find the user''s profile.',
'    SCH_APP_USER u',
'-- Step 4: Use the GUARDIAN_ID from the user''s profile to find all links in the student/guardian table.',
'JOIN',
'    SCH_STUDENT_GUARDIAN sg ON u.GUARDIAN_ID = sg.GUARDIAN_ID',
'-- Step 5: Get the details for each student found.',
'JOIN',
'    SCH_STUDENT s ON sg.STUDENT_ID = s.STUDENT_ID',
'-- This join is for checking the user''s role.',
'JOIN',
'    SCH_APP_USER_ROLE aur ON u.APP_USER_ID = aur.APP_USER_ID',
'WHERE',
'    -- Step 1: Anchor the entire query to the currently logged-in user.',
'   UPPER(u.USER_NAME) = UPPER(:APP_USER)',
'',
'    -- Step 3: A crucial check to make sure the user''s profile actually has a GUARDIAN_ID.',
'    --AND u.GUARDIAN_ID IS NOT NULL',
'',
'    -- The rest of the WHERE clause validates roles and active status.',
'      --AND aur.ROLE_CODE = ''PARENT''',
'      --AND aur.IS_ACTIVE = ''Y''',
'      --AND TRUNC(SYSDATE) >= aur.EFFECTIVE_FROM',
'      --AND (aur.EFFECTIVE_TO IS NULL OR TRUNC(SYSDATE) <= aur.EFFECTIVE_TO)',
'      --AND s.ACTIVE_YN = ''Y''',
'ORDER BY',
'    s.LAST_NAME, s.FIRST_NAME;',
'',
'',
'',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P300_HIDDEN_STUDENT_ID'
,p_prn_page_header=>'Parent_My_Students_Main'
);
