,p_plug_name=>'My_Children_Medical_Records_Main'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    s.STUDENT_ID,',
'    s.FIRST_NAME || '' '' || s.LAST_NAME AS STUDENT_NAME,',
'    s.STUDENT_NO,',
'    sm.CONDITIONS,         -- Corrected',
'    sm.ALLERGIES,          -- Corrected',
'    sm.MEDICATIONS,        -- Corrected',
'    sm.PHYSICIAN_NAME,',
'    sm.PHYSICIAN_PHONE,',
'    sm.NOTES,',
'    sm.UPDATED_ON AS LAST_UPDATED',
'FROM',
'    SCH_APP_USER u',
'JOIN',
'    SCH_APP_USER_ROLE aur ON u.APP_USER_ID = aur.APP_USER_ID',
'JOIN',
'    SCH_STUDENT_GUARDIAN sg ON u.GUARDIAN_ID = sg.GUARDIAN_ID',
'JOIN',
'    SCH_STUDENT s ON sg.STUDENT_ID = s.STUDENT_ID',
'JOIN',
'    SCH_STUDENT_MEDICAL sm ON s.STUDENT_ID = sm.STUDENT_ID',
'WHERE',
'    -- 1. Anchor to the currently logged-in user',
'    UPPER(u.USER_NAME) = UPPER(:APP_USER)',
'',
'    -- 2. Ensure the user''s account is valid and linked to a guardian profile',
'    AND u.IS_ACTIVE_YN = ''Y''',
'    AND u.GUARDIAN_ID IS NOT NULL',
'',
'    -- 3. Security: Confirm the user has an active ''PARENT'' role',
'    AND aur.ROLE_CODE = ''PARENT''',
'    AND aur.IS_ACTIVE = ''Y''',
'    AND TRUNC(SYSDATE) BETWEEN aur.EFFECTIVE_FROM AND NVL(aur.EFFECTIVE_TO, TRUNC(SYSDATE))',
'',
'    -- 4. Ensure the student''s record is currently active',
'    AND s.ACTIVE_YN = ''Y''',
'ORDER BY',
'    STUDENT_NAME,',
'    sm.UPDATED_ON DESC;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'My_Children_Medical_Records_Main'
);
