wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(265668366420000321654)
,p_plug_name=>'My_Students_Main'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'',
'    -- Teacher Information',
'    u.USER_NAME AS TEACHER_USERNAME,',
'    ',
'    -- Class and Section Information',
'    c.CLASS_NAME,',
'    s.SECTION_CODE,',
'    t.TERM_NAME,',
'    ',
'    -- Student Information',
'    st.FIRST_NAME,',
'    st.LAST_NAME,',
'    st.STUDENT_NO,',
'    st.STUDENT_ID,',
'    gl.GRADE_LEVEL_NAME',
'FROM',
'    SCH_APP_USER u -- Start with the teacher',
'JOIN',
'    SCH_USER_SECTION_SCOPE uss ON u.APP_USER_ID = uss.APP_USER_ID -- Find the sections they are assigned to',
'JOIN',
'    SCH_SECTION s ON uss.SECTION_ID = s.SECTION_ID -- Get details for each section',
'JOIN',
'    SCH_CLASS c ON s.CLASS_ID = c.CLASS_ID -- Get the name of the class',
'JOIN',
'    SCH_ENROLLMENT e ON s.SECTION_ID = e.SECTION_ID -- Find all student enrollments in those sections',
'JOIN',
'    SCH_STUDENT st ON e.STUDENT_ID = st.STUDENT_ID -- Get the details for each enrolled student',
'JOIN',
'    SCH_TERM t ON s.TERM_ID = t.TERM_ID -- Get the name of the academic term',
'JOIN',
'    SCH_GRADE_LEVEL gl ON st.GRADE_LEVEL_CODE = gl.GRADE_LEVEL_CODE -- Get the student''s grade level',
'WHERE',
'    u.APP_USER_ID = :P500_USER_ID -- <-- This is where you put the teacher''s ID',
'ORDER BY',
'    c.CLASS_NAME,    -- Group results by class',
'    s.SECTION_CODE,  -- Then by section',
'    st.LAST_NAME,    -- And finally, list students alphabetically',
'    st.FIRST_NAME;',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'My_Students_Main'
,p_ai_enabled=>false
);
