,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'',
'    -- Teacher Information',
'    u.USER_NAME AS TEACHER_USERNAME,',
'    ',
'    -- Class and Section Information',
'    c.CLASS_NAME,',
'    s.SECTION_CODE,',
'    t.TERM_NAME,',
'    ',
'    -- Student Information',
'    st.FIRST_NAME,',
'    st.LAST_NAME,',
'    st.STUDENT_NO,',
'    st.STUDENT_ID,',
'    gl.GRADE_LEVEL_NAME',
'FROM',
'    SCH_APP_USER u -- Start with the teacher',
'JOIN',
