wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(132860015475493413113)
,p_name=>'Grades'
,p_parent_plug_id=>wwv_flow_imp.id(132858639874638376409)
,p_template=>4072358936313175081
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    e.STUDENT_ID,',
'    u.APP_USER_ID,',
'    -- Term/Semester Information',
'    t.TERM_NAME,',
'    ',
'    -- Class and Teacher Information',
'    c.CLASS_NAME,',
'    u.USER_NAME AS TEACHER_USERNAME,',
'    ',
'    -- **THE FIX**: Aggregated Grade Information',
'    ROUND(AVG(g.SCORE_PERCENT), 2) AS AVERAGE_SCORE,',
'    CASE',
'        WHEN AVG(g.SCORE_PERCENT) >= 90 THEN ''A''',
'        WHEN AVG(g.SCORE_PERCENT) >= 80 THEN ''B''',
'        WHEN AVG(g.SCORE_PERCENT) >= 70 THEN ''C''',
'        WHEN AVG(g.SCORE_PERCENT) >= 60 THEN ''D''',
'        ELSE ''F''',
'    END AS FINAL_LETTER_GRADE',
'FROM',
'    SCH_ENROLLMENT e',
'JOIN',
'    SCH_STUDENT st ON e.STUDENT_ID = st.STUDENT_ID',
'JOIN',
'    SCH_SECTION s ON e.SECTION_ID = s.SECTION_ID',
'JOIN',
'    SCH_CLASS c ON s.CLASS_ID = c.CLASS_ID',
'JOIN',
'    SCH_TERM t ON s.TERM_ID = t.TERM_ID',
'JOIN',
'    SCH_USER_SECTION_SCOPE uss ON s.SECTION_ID = uss.SECTION_ID',
'JOIN',
'    SCH_APP_USER u ON uss.APP_USER_ID = u.APP_USER_ID',
'LEFT JOIN',
'    SCH_GRADE g ON e.ENROLLMENT_ID = g.ENROLLMENT_ID',
'WHERE',
'   st.STUDENT_ID = :P502_HIDDEN_STUDENT_ID',
'     AND u.APP_USER_ID = :P502_HIDDEN_TEACHER_ID',
'GROUP BY',
'    -- **THE FIX**: Group by all the non-aggregated columns',
'    e.STUDENT_ID,',
'    u.APP_USER_ID,',
'    t.TERM_NAME,',
'    c.CLASS_NAME,',
'    u.USER_NAME,',
'    t.START_DATE',
'ORDER BY',
'    t.START_DATE DESC,',
'    c.CLASS_NAME;',
''))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2538654340625403440
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
