,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    INSERT INTO SCH_TERM (',
'        TERM_CODE,',
'        TERM_NAME,',
'        START_DATE,',
'        END_DATE,',
'        ACTIVE_YN,',
'        -- Explicitly setting audit columns for clarity',
'        CREATED_ON,',
'        CREATED_BY',
'    ) VALUES (',
'        :P1004_TERM_CODE,',
'        :P1004_TERM_NAME,',
'        :P1004_START_DATE,',
'        :P1004_END_DATE,',
'        :P1004_ACTIVE_YN,',
'        -- Use the database system time and current APEX user',
'        systimestamp,',
'        V(''APP_USER'')',
'    )',
'    -- This clause retrieves the new ID and places it back into the page item',
'    RETURNING TERM_ID INTO :P1004_TERM_ID;',
'END;',
''))
,p_attribute_02=>'P1004_TERM_ID,P1004_TERM_CODE,P1004_TERM_NAME,P1004_START_DATE,P1004_END_DATE,P1004_ACTIVE_YN,P1004_CREATED_ON,P1004_CREATED_BY,P1004_UPDATED_ON,P1004_UPDATED_BY'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
