,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    UPDATE SCH_APP_USER_ROLE',
'    SET',
'        EFFECTIVE_FROM = :P1018_EFFECTIVE_FROM,',
'        EFFECTIVE_TO   = :P1018_EFFECTIVE_TO,',
'        IS_ACTIVE      = :P1018_IS_ACTIVE,',
'        -- Set the audit columns for the update operation',
'        UPDATED_ON     = sysdate,',
'        UPDATED_BY     = V(''APP_USER'') -- Gets the current APEX user',
'    WHERE',
'        -- Use both parts of the composite primary key to identify the record',
'        APP_USER_ID = :P1018_APP_USER_ID',
'        AND ROLE_CODE   = :P1018_ROLE_CODE;',
'END;',
''))
,p_attribute_02=>'P1018_APP_USER_ID,P1018_ROLE_CODE,P1018_EFFECTIVE_FROM,P1018_EFFECTIVE_TO,P1018_IS_ACTIVE,P1018_CREATED_ON,P1018_CREATED_BY,P1018_UPDATED_ON,P1018_UPDATED_BY'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
