wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(130069403273386180215)
,p_event_id=>wwv_flow_imp.id(130069403181808180214)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_name=>'CREATE Code'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    MERGE INTO SCH_APP_USER_ROLE dest',
'    USING (',
'        SELECT',
'            :P1018_APP_USER_ID  AS app_user_id,',
'            :P1018_ROLE_CODE     AS role_code',
'        FROM dual',
'    ) src ON (',
'        dest.app_user_id = src.app_user_id AND',
'        dest.role_code   = src.role_code',
'    )',
'    WHEN NOT MATCHED THEN',
'        INSERT (',
'            APP_USER_ID,',
'            ROLE_CODE,',
'            EFFECTIVE_FROM,',
'            EFFECTIVE_TO,',
'            IS_ACTIVE,',
'            -- The database handles CREATED_ON and CREATED_BY with defaults,',
'            -- but we can set them explicitly if needed.',
'            CREATED_BY',
'        )',
'        VALUES (',
'            :P1018_APP_USER_ID,',
'            :P1018_ROLE_CODE,',
'            :P1018_EFFECTIVE_FROM,',
'            :P1018_EFFECTIVE_TO,',
'            :P1018_IS_ACTIVE,',
'            V(''APP_USER'')',
'        );',
'END;',
''))
,p_attribute_02=>'P1018_APP_USER_ID,P1018_ROLE_CODE,P1018_EFFECTIVE_FROM,P1018_EFFECTIVE_TO,P1018_IS_ACTIVE,P1018_CREATED_ON,P1018_CREATED_BY,P1018_UPDATED_ON,P1018_UPDATED_BY'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
